{"witnessCode": "import { describe, it } from 'node:test';
import { strict as assert } from 'node:assert/strict';
import normalizeUrl from '../index.js';

describe('normalizeUrl', () => {
  it('should normalize a URL with a custom protocol containing a dot', () => {
    const input = 'foo.bar:baz';
    const expected = 'foo:foo.bar:baz';
    const actual = normalizeUrl(input, { defaultProtocol: 'foo' });
    assert.strictEqual(actual, expected);
  });
});"}
